"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["77306"],{23224(e){e.exports=JSON.parse('{"id":"V4-067","slug":"earnings-guidance","term":"Earnings Guidance","also_known_as":[],"difficulty":"Intermediate","definition":"Earnings guidance is a company\u2019s own forecast of its future financial results, such as expected revenue, profit or earnings per share for an upcoming quarter or year, shared publicly with investors.","explanation":["Companies provide guidance to help investors and analysts understand their expectations. Guidance may be a single figure or, more often, a range, such as expected earnings per share of 2.40 to 2.60 for the year.","When a company raises its guidance, it usually signals stronger expectations, and its share price may rise. Lowering guidance can cause the share price to fall. Analysts\u2019 forecasts often cluster around company guidance.","For example, a company might report quarterly results and say it now expects full-year revenue growth of 8% to 10%, up from its earlier guidance of 6% to 8%.","Guidance practices vary. Many US companies provide quarterly or annual guidance, while some prefer not to, arguing it encourages short-term thinking and pressure to meet targets. In some countries, companies are required to update the market if results will differ significantly from expectations. Guidance is a forecast, not a promise, and actual results can differ."],"note":"","total":1725,"prev":{"slug":"earnings-growth","term":"Earnings Growth"},"next":{"slug":"earnings-management","term":"Earnings Management"}}')}}]);